"""Parse json or csv; unknown formats keep a stable error message."""
import csv
import io
import json

_PARSERS = {"json": json.loads, "csv": lambda text: list(csv.reader(io.StringIO(text)))}

def parse(fmt, text):
    if fmt not in _PARSERS:
        raise ValueError(f"unknown format: {fmt}")
    return _PARSERS[fmt](text)

def register_parser(fmt, parser):
    if not isinstance(fmt, str) or not fmt or not callable(parser):
        raise ValueError("invalid parser registration")
    if fmt in _PARSERS:
        raise ValueError("parser already registered")
    _PARSERS[fmt] = parser
